INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP2023_Chapter04+as+on+20.04.2026.pdf', '4', 'Duty Exemption / Remission Schemes', '4.09', 'Cases requiring Sanitary Import Permit.', '(i) Where import of meat and meat products of any kind including fresh, chilled
